using System.IO;
using System.Security.Cryptography;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using RAWSelectionAssistant.Core.Services.Projects;
using RAWSelectionAssistant.ViewModels;
using RAWSelectionAssistant.Views;
using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public class ViewingLifecycleTests
{
 static BitmapSource Image(byte value){var b=BitmapSource.Create(20,10,96,96,PixelFormats.Rgb24,null,Enumerable.Repeat(value,600).ToArray(),60);b.Freeze();return b;}
 static ReferenceColorWorkspaceViewModel Workspace(int count=2){EnsureTestApplication();var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());for(int i=0;i<count;i++){var id=Guid.NewGuid();var hash=new string('A',64);var version=new StudioEditVersion(id,"fixed"+i,DateTimeOffset.UnixEpoch,null,null,hash,null,null,null,ColorStudioMatchEngine.Stable,MatchV4ExecutionMode.Auto){IsOriginal=true};var target=new ReferenceTargetItem("test"+i+".png"){SourceHash=hash,IsSelected=true,ActiveEditVersionId=id};target.EditVersions.Add(version);vm.Targets.Add(target);}vm.PinSelectedViewingVariants();vm.ViewingRenderOverride=(_,_,_)=>Task.FromResult(Image(40));return vm;}
 sealed class Blocked{public TaskCompletionSource<BitmapSource> Completion=new(TaskCreationOptions.RunContinuationsAsynchronously);public CancellationToken Token;public Task<BitmapSource> Render(ViewingTableItem i,int edge,CancellationToken token){Token=token;return Completion.Task;}}
 [TestMethod]public Task DetailThenCompareRejectsLateSuccessAndLateError()=>RunSta(async()=>{using var vm=Workspace();await vm.PrepareViewingTableAsync();var view=new StudioViewingTableView(vm);var blocked=new Blocked();view.DetailRenderer=blocked.Render;view.SelectFrame(vm.ViewingFrames[0]);var old=view.ShowDetailAsync();await view.CompareAsync();var comparison=view.DetailContent;Assert.IsInstanceOfType<DockPanel>(comparison);blocked.Completion.SetResult(Image(90));await old;Assert.AreSame(comparison,view.DetailContent);Assert.IsTrue(blocked.Token.IsCancellationRequested);
 var failed=new Blocked();view.DetailRenderer=failed.Render;var request=view.ShowDetailAsync();await view.CompareAsync();var text=view.VisibleStatus;failed.Completion.SetException(new IOException("obsolete failure"));await request;Assert.AreEqual(text,view.VisibleStatus);Assert.IsInstanceOfType<DockPanel>(view.DetailContent);view.Close();});
 [TestMethod]public Task ReverseDetailCompletionKeepsBAndStopRejectsInFlightSlide()=>RunSta(async()=>{using var vm=Workspace();await vm.PrepareViewingTableAsync();var view=new StudioViewingTableView(vm);var a=new Blocked();var b=new Blocked();int calls=0;view.DetailRenderer=(i,e,t)=>++calls==1?a.Render(i,e,t):b.Render(i,e,t);view.SelectFrame(vm.ViewingFrames[0]);var aa=view.ShowDetailAsync();view.SelectFrame(vm.ViewingFrames[1]);var bb=view.ShowDetailAsync();b.Completion.SetResult(Image(80));await bb;var content=view.DetailContent;a.Completion.SetResult(Image(30));await aa;Assert.AreSame(content,view.DetailContent);
 var slide=new Blocked();view.DetailRenderer=slide.Render;var pending=view.ShowDetailAsync();view.StopSlideshow();slide.Completion.SetResult(Image(100));await pending;Assert.AreSame(content,view.DetailContent);Assert.IsTrue(slide.Token.IsCancellationRequested);view.Close();});
 [TestMethod]public Task RefreshCrossingCloseAndOldFailureNeverFillNewView()=>RunSta(async()=>{using var vm=Workspace();await vm.PrepareViewingTableAsync();var view=new StudioViewingTableView(vm);var a=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var b=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);int calls=0;var startedA=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var startedB=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);view.RefreshLoader=t=>{if(++calls==1){startedA.SetResult();return a.Task;}startedB.SetResult();return b.Task;};var aa=view.RefreshAsync();await startedA.Task;var bb=view.RefreshAsync();await startedB.Task;b.SetResult();await bb;var status=view.VisibleStatus;a.SetException(new IOException("stale refresh"));await aa;Assert.AreEqual(status,view.VisibleStatus);
 var decoder=new Blocked();view.DetailRenderer=decoder.Render;view.SelectFrame(vm.ViewingFrames[0]);var pending=view.ShowDetailAsync();view.Close();decoder.Completion.SetResult(Image(90));await pending;Assert.IsNull(view.DetailContent);Assert.AreEqual(0,view.RealizedCardCount);Assert.IsTrue(decoder.Token.IsCancellationRequested);
 });
 [TestMethod]public Task WorkspaceProgressiveLatestSnapshotAndCancellationAreDeterministic()=>RunSta(async()=>{using var vm=Workspace();var a=new Blocked();var b=new Blocked();int calls=0;var second=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);vm.ViewingRenderOverride=(i,e,t)=>{if(++calls==1)return a.Render(i,e,t);second.TrySetResult();return b.Render(i,e,t);};var old=vm.PrepareViewingTableAsync();var current=vm.PrepareViewingTableAsync();await second.Task;b.Completion.SetResult(Image(70));await current;Assert.AreEqual(2,vm.ViewingFrames.Count);var image=vm.ViewingFrames[0].Image;a.Completion.SetResult(Image(20));await old;Assert.AreSame(image,vm.ViewingFrames[0].Image);
 var block=new Blocked();calls=0;vm.ViewingRenderOverride=(i,e,t)=>++calls==1?Task.FromResult(Image(60)):block.Render(i,e,t);var ready=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);vm.PropertyChanged+=(_,e)=>{if(e.PropertyName==nameof(vm.ViewingFrames)&&vm.ViewingFrames.Count==1)ready.TrySetResult();};var work=vm.PrepareViewingTableAsync();await ready.Task;Assert.AreEqual(1,vm.ViewingFrames.Count);vm.ReleaseViewing();block.Completion.TrySetResult(Image(30));await work;Assert.AreEqual(0,vm.ViewingFrames.Count);Assert.AreEqual(0,vm.ViewingCacheBytes);
 });
 [TestMethod]public Task VirtualCardsStayBoundedWithHundredPinnedPlaceholders()=>RunSta(async()=>{using var vm=Workspace(100);var blocked=new Blocked();vm.ViewingRenderOverride=blocked.Render;var view=new StudioViewingTableView(vm);view.Measure(new Size(1200,800));view.Arrange(new Rect(0,0,1200,800));view.UpdateLayout();var work=view.RefreshAsync();Assert.IsTrue(view.RealizedCardCount>0);Assert.IsTrue(view.RealizedCardCount<=32);view.Close();blocked.Completion.TrySetResult(Image(40));await work;Assert.AreEqual(0,view.RealizedCardCount);});
 [TestMethod]public Task CacheHitChecksHandleChangeEvenWithSameLengthAndRestoredMtime()=>RunSta(async()=>{EnsureTestApplication();var root=Path.Combine(Path.GetTempPath(),"view-identity-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var path=Path.Combine(root,"fixed.bmp");var encoder=new BmpBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(Image(30)));using(var f=File.Create(path))encoder.Save(f);using var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());await vm.LoadTargetAsync(path);await vm.CreateR53VariantAsync(true);vm.ActiveTarget!.IsSelected=true;vm.PinSelectedViewingVariants();await vm.PrepareViewingTableAsync();Assert.AreEqual(1,vm.ViewingFrames.Count);var reads=vm.ViewingHashReads;var decodes=vm.ViewingDecodeCount;await vm.PrepareViewingTableAsync();Assert.AreEqual(reads,vm.ViewingHashReads);Assert.AreEqual(decodes,vm.ViewingDecodeCount);var modified=File.GetLastWriteTimeUtc(path);var bytes=File.ReadAllBytes(path);bytes[^1]^=1;File.WriteAllBytes(path,bytes);File.SetLastWriteTimeUtc(path,modified);await vm.PrepareViewingTableAsync();Assert.AreEqual(0,vm.ViewingFrames.Count);Assert.IsTrue(vm.ViewingHashReads>reads);Assert.IsTrue(vm.ViewingFailures.Single().Contains("变化"));vm.ReleaseViewing();Assert.AreEqual(0,vm.ViewingCacheBytes);});
 [TestMethod]public Task ActualWorkspaceCloseDuringDecoderDiscardsAndReleasesCache()=>RunSta(async()=>{
  EnsureTestApplication();var root=Path.Combine(Path.GetTempPath(),"view-decode-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var path=Path.Combine(root,"owned.cr3");await File.WriteAllBytesAsync(path,[1,2,3]);var decoder=new ControlledRaw();using var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs(),rawDecoder:decoder);var hash=Convert.ToHexString(SHA256.HashData([1,2,3]));var v=new StudioEditVersion(Guid.NewGuid(),"frozen",DateTimeOffset.UnixEpoch,null,null,hash,null,null,null,ColorStudioMatchEngine.Stable,MatchV4ExecutionMode.Auto){IsOriginal=true};var target=new ReferenceTargetItem(path){IsSelected=true,SourceHash=hash,ActiveEditVersionId=v.Id};target.EditVersions.Add(v);vm.Targets.Add(target);vm.PinSelectedViewingVariants();var ledger=StudioGlobalResources.AccountedBytes;var work=vm.PrepareViewingTableAsync();await decoder.Started.Task;vm.ReleaseViewing();decoder.Completion.SetResult(RAWSelectionAssistant.Core.Models.RawDecodedImage.FromRgb48(20,10,120,Enumerable.Repeat((ushort)22000,600).ToArray(),new("owned","test",null,1,"sRGB")));await work;Assert.AreEqual(0,vm.ViewingFrames.Count);Assert.AreEqual(0,vm.ViewingCacheBytes);Assert.AreEqual(ledger,StudioGlobalResources.AccountedBytes);Assert.IsTrue(decoder.Token.IsCancellationRequested);
 });
 sealed class ControlledRaw:RAWSelectionAssistant.Core.Services.RawToJpeg.IRawDecoder{public TaskCompletionSource Started=new(TaskCreationOptions.RunContinuationsAsynchronously);public TaskCompletionSource<RAWSelectionAssistant.Core.Models.RawDecodedImage> Completion=new(TaskCreationOptions.RunContinuationsAsynchronously);public CancellationToken Token;public RAWSelectionAssistant.Core.Models.RawDecoderCapability GetCapability()=>throw new NotSupportedException();public Task<RAWSelectionAssistant.Core.Models.RawDecodedImage> DecodeAsync(string path,RAWSelectionAssistant.Core.Models.RawToJpegOptions options,CancellationToken token=default){Token=token;Started.SetResult();return Completion.Task;}}

 [TestMethod]public Task RetryOnlyFailedItemKeepsSuccessfulFramesAndScrollCancelsObsoleteWork()=>RunSta(async()=>{using var vm=Workspace(100);int calls=0;var first=vm.ViewingTable.Items[0];vm.ViewingRenderOverride=(i,e,t)=>{calls++;return i.VariantId==first.VariantId?Task.FromException<BitmapSource>(new IOException("retry-owned")):Task.FromResult(Image(40));};await vm.PrepareViewingTableAsync();Assert.AreEqual(99,vm.ViewingFrames.Count);Assert.AreEqual(1,vm.ViewingFailures.Count);var good=vm.ViewingFrames[0].Image;calls=0;vm.ViewingRenderOverride=(i,e,t)=>{calls++;return Task.FromResult(Image(50));};await vm.RetryViewingItemAsync(first);Assert.AreEqual(1,calls);Assert.AreEqual(100,vm.ViewingFrames.Count);Assert.AreEqual(0,vm.ViewingFailures.Count);Assert.AreSame(good,vm.ViewingFrames.First(f=>f.Item.VariantId!=first.VariantId).Image);
 var view=new StudioViewingTableView(vm);view.Measure(new Size(1200,800));view.Arrange(new Rect(0,0,1200,800));view.UpdateLayout();var old=new Blocked();var started=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);vm.ViewingRenderOverride=(i,e,t)=>{started.TrySetResult();return old.Render(i,e,t);};var pending=view.RefreshAsync();await started.Task;var obsoleteToken=old.Token;view.ScrollForTest(2300);view.UpdateLayout();await System.Windows.Threading.Dispatcher.Yield(System.Windows.Threading.DispatcherPriority.Background);Assert.IsTrue(obsoleteToken.IsCancellationRequested);view.Close();old.Completion.TrySetResult(Image(60));await pending;await view.ViewportWork;Assert.AreEqual(0,vm.ViewingFrames.Count);});

 [TestMethod]public Task TwoVariantsOneSourceRetryKeepsOtherFailure()=>RunSta(async()=>{using var vm=Workspace();var first=vm.ViewingTable.Items[0];var second=vm.ViewingTable.Items[1] with{TargetId=first.TargetId};vm.Layout=vm.Layout with{ViewingTable=vm.ViewingTable with{Items=[first,second]}};vm.ViewingRenderOverride=(i,e,t)=>Task.FromException<BitmapSource>(new IOException("owned"));await vm.PrepareViewingTableAsync();Assert.AreEqual(2,vm.ViewingFailures.Count);vm.ViewingRenderOverride=(i,e,t)=>Task.FromResult(Image(40));await vm.RetryViewingItemAsync(first);Assert.AreEqual(1,vm.ViewingFailures.Count);Assert.IsTrue(vm.ViewingFailures.Single().Contains(second.VariantId.ToString()));});

}
